# apply_feature_push_and_run.py — drops 5 updated files and reruns the walk-forward
# comparison with new features + per-track-type T. Best previous matchup LL: 0.6206.
import base64, sys, pathlib

FILES = {
    'src/features/rolling.py': '',
    'src/features/build_features.py': '',
    'src/models/gbm_ranker.py': '',
    'src/models/calibrate.py': '',
    'src/eval/backtest_gbm_walkforward.py': '',
}


def main():
    for target, b64 in FILES.items():
        p = pathlib.Path(target)
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_bytes(base64.b64decode(b64))
        print(f"wrote {target}")

    import pandas as pd
    from src.eval.backtest_gbm_walkforward import backtest_gbm_walkforward, summarize_wf

    races = pd.read_parquet("data/processed/races.parquet").sort_values("date").reset_index(drop=True)
    entries = pd.read_parquet("data/processed/entries.parquet")
    sessions = pd.read_parquet("data/processed/sessions.parquet")
    loopstats = pd.read_parquet("data/processed/loopstats.parquet")

    print("\nAlpha sweep with new features (global T)")
    results_global = {}
    for alpha in [0.85, 0.7, 0.55]:
        out = backtest_gbm_walkforward(
            races, entries, sessions, loopstats,
            initial_train_races=36, retrain_every_n=10,
            calib_window=25, recalibrate_every_n=10,
            ensemble_alpha=alpha, n_samples=3000, per_type_T=False,
        )
        s = summarize_wf(out["metrics"])
        results_global[alpha] = s.loc["ALL"]
        print(f"  alpha={alpha}: matchup_ll={s.loc['ALL','matchup_logloss']:.4f}  "
              f"winner_ll={s.loc['ALL','winner_logloss']:.4f}  "
              f"top5={s.loc['ALL','top5_accuracy']:.4f}")

    best_alpha = min(results_global, key=lambda a: results_global[a]["matchup_logloss"])
    print(f"\nBest alpha (global T): {best_alpha}")

    print(f"\nBest alpha with per-track-type T")
    out = backtest_gbm_walkforward(
        races, entries, sessions, loopstats,
        initial_train_races=36, retrain_every_n=10,
        calib_window=25, recalibrate_every_n=10,
        ensemble_alpha=best_alpha, n_samples=3000, per_type_T=True,
    )
    s_pt = summarize_wf(out["metrics"])
    print(s_pt.round(4).to_string())

    print(f"\n=== Comparison for best alpha={best_alpha} ===")
    row_g = results_global[best_alpha][["winner_logloss","matchup_logloss","spearman_rho","top5_accuracy"]]
    row_pt = s_pt.loc["ALL"][["winner_logloss","matchup_logloss","spearman_rho","top5_accuracy"]]
    print(pd.DataFrame({"global T": row_g, "per-type T": row_pt}).round(4).to_string())

    # Feature importance
    try:
        booster = out["model"].booster
        imp = pd.DataFrame({
            "feature": booster.feature_name(),
            "gain": booster.feature_importance(importance_type="gain"),
        }).sort_values("gain", ascending=False).head(20)
        print("\nTop 20 features by gain (per-type run):")
        print(imp.to_string(index=False))
    except Exception as e:
        print(f"(feat importance skipped: {e})")

if __name__ == "__main__":
    main()
